import{_ as e,a as o,b as r,c as a,d as l}from"./chunks/14d-tabs-context-menu.3DeBt3Hb.js";import{_ as i,o as s,c as n,a2 as d}from"./chunks/framework.DUZafPzB.js";const x=JSON.parse('{"title":"多标签预览","description":"","frontmatter":{},"headers":[],"relativePath":"zh/features/tabs.md","filePath":"zh/features/tabs.md","lastUpdated":null}'),c={name:"zh/features/tabs.md"};function h(g,t,p,b,u,f){return s(),n("div",null,[...t[0]||(t[0]=[d('<h1 id="多标签预览" tabindex="-1">多标签预览 <a class="header-anchor" href="#多标签预览" aria-label="Permalink to &quot;多标签预览&quot;">​</a></h1><p>桌面端的预览区是一个<strong>多标签工作区</strong>：PDF 报告、图、代码、表格、Markdown、Office 文档可以同时打开，像浏览器标签一样切换、固定和批量关闭，不用来回点文件列表。</p><p><img src="'+e+'" alt="多标签预览：6 个标签，当前为 PDF 报告（相关性热图 + QC 表）"></p><h2 id="打开标签" tabindex="-1">打开标签 <a class="header-anchor" href="#打开标签" aria-label="Permalink to &quot;打开标签&quot;">​</a></h2><ul><li>在 <strong>Files</strong>、<strong>Explorer</strong>、<strong>Collections</strong> 里点一个文件，就在右侧预览区为它打开一个标签；再点另一个文件会<strong>追加</strong>一个新标签，并切换过去。</li><li>同一个文件（同一 Agent + root + 路径）<strong>只会有一个标签</strong>：再次点击只是切回已有标签，不会重复打开，也<strong>不会重置</strong>它的阅读位置。</li><li>从 <a href="/filebox/zh/features/search">工作区搜索</a> 结果点 <strong>Open in preview pane</strong>，同样以标签打开；若该文件已有标签，会强制重新读取一次，避免看到旧内容。</li><li>只有 <strong>1 个</strong>标签时不显示标签栏，界面与单文件预览一致；打开第 2 个起出现标签栏。</li><li>三个视图共用同一组标签：在 Files 打开的标签，切到 Explorer / Collections 仍然在。</li></ul><h2 id="切换标签" tabindex="-1">切换标签 <a class="header-anchor" href="#切换标签" aria-label="Permalink to &quot;切换标签&quot;">​</a></h2><p><img src="'+o+'" alt="切换到代码标签 qc_pipeline.py（Monaco 只读高亮）"></p><ul><li><strong>点击标签</strong>即可切换；当前标签有顶部强调色细线。标签上显示文件名，鼠标悬停显示完整的 <code>root/路径</code>。</li><li>标签较多、标签栏放不下时可横向滚动，当前标签会自动滚入视野。</li><li>标签栏最右侧的 <strong>数字 + ⌄</strong> 按钮（如 <code>6 ⌄</code>）打开 <strong>Open previews</strong> 列表：列出所有已打开的文件名和完整路径，点击即跳转。列表支持键盘：<code>↑</code> / <code>↓</code> 移动、<code>Home</code> / <code>End</code> 跳到首尾、<code>Enter</code> 打开、<code>Esc</code> 关闭。</li></ul><p><img src="'+r+'" alt="Open previews 跳转列表"></p><p><img src="'+a+'" alt="切换到图片标签 growth-kinetics.png（已固定）"></p><h2 id="固定-pin-标签" tabindex="-1">固定（Pin）标签 <a class="header-anchor" href="#固定-pin-标签" aria-label="Permalink to &quot;固定（Pin）标签&quot;">​</a></h2><p>每个标签的文件名右侧有一个 <strong>图钉</strong> 按钮：</p><table tabindex="0"><thead><tr><th>状态</th><th>切走再切回来时</th></tr></thead><tbody><tr><td>未固定（默认）</td><td>预览会重新加载：PDF 回到第 1 页、缩放与滚动位置重置。后台不占用浏览器资源。</td></tr><tr><td>已固定（图钉变为实心强调色）</td><td>预览在后台<strong>保持挂载</strong>，切回来是瞬时的，并保留 PDF 页码 / 缩放、图片缩放、代码滚动位置等状态。</td></tr></tbody></table><ul><li>也可以右键标签 → <strong>Pin tab / Unpin tab</strong>。</li><li>固定是按标签单独选择的；每个固定的标签都会一直占用内存（尤其是 HTML 预览），只固定你需要反复对照的文件。</li><li>在 Open previews 列表里，已固定的标签名前有一个小图钉。</li></ul><h2 id="关闭标签" tabindex="-1">关闭标签 <a class="header-anchor" href="#关闭标签" aria-label="Permalink to &quot;关闭标签&quot;">​</a></h2><p><img src="'+l+'" alt="右键标签菜单"></p><ul><li>标签上的 <strong>×</strong>：关闭这个标签。</li><li>预览头部右侧的 <strong>×</strong>（提示 <em>Close (Esc)</em>）：关闭当前标签。</li><li><strong>右键标签</strong>弹出菜单： <ul><li><strong>Pin tab / Unpin tab</strong></li><li><strong>Close tab</strong> — 关闭此标签</li><li><strong>Close tabs to the left</strong> — 关闭左侧所有标签（最左一个时不可用）</li><li><strong>Close tabs to the right</strong> — 关闭右侧所有标签（最右一个时不可用）</li><li><strong>Close all tabs</strong> — 全部关闭</li></ul></li><li>关闭当前标签后，自动切到<strong>相邻</strong>标签（优先右边，与浏览器一致）。</li></ul><h2 id="键盘快捷键" tabindex="-1">键盘快捷键 <a class="header-anchor" href="#键盘快捷键" aria-label="Permalink to &quot;键盘快捷键&quot;">​</a></h2><p>在 Files / Explorer / Collections 视图、焦点不在输入框里时生效：</p><table tabindex="0"><thead><tr><th>按键</th><th>作用</th></tr></thead><tbody><tr><td><code>Esc</code></td><td>关闭当前标签（若 Search 浮窗开着，先关浮窗；右键菜单 / 跳转列表开着时只关菜单）</td></tr><tr><td><code>←</code> / <code>→</code></td><td><strong>仅 Files 视图</strong>：在当前标签里切到同一目录的上一个 / 下一个文件（要求文件列表正停在该文件所在目录）。目标文件已有标签时直接切过去，不会删掉你打开的其他标签</td></tr><tr><td><code>↑</code> <code>↓</code> <code>Home</code> <code>End</code> <code>Enter</code> <code>Esc</code></td><td>在 Open previews 跳转列表中导航</td></tr></tbody></table><h2 id="预览区宽度" tabindex="-1">预览区宽度 <a class="header-anchor" href="#预览区宽度" aria-label="Permalink to &quot;预览区宽度&quot;">​</a></h2><p>文件列表与预览区之间的分隔条可以左右拖动（列表占 20%–80%），比例保存在浏览器本地，下次打开沿用。标签多时把预览区拖宽一些，标签栏能完整显示更多标签。</p><h2 id="行为说明" tabindex="-1">行为说明 <a class="header-anchor" href="#行为说明" aria-label="Permalink to &quot;行为说明&quot;">​</a></h2><ul><li>多标签工作区用于桌面端（窗口宽度 ≥ 768 px）；手机 / 窄窗口使用「列表 ↔ 全屏预览」单文件模式。</li><li>标签属于当前页面会话：刷新或重新打开页面后，从一个干净的工作区开始。</li><li><strong>切换 Agent</strong> 会关闭全部标签（预览不会跨机器保留）；在 Settings 里停用 / 删除某个 root 时，该 root 下的标签会被自动关闭。</li><li>标签数量不设上限；未固定的后台标签不占预览资源，固定的标签常驻后台。</li><li>预览头部的刷新按钮（<em>Refresh preview</em>）会重新读取当前标签的文件；<strong>Download</strong> 与复制完整服务器地址按钮针对当前标签。</li><li>标签按打开顺序排列。</li></ul><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/filebox/zh/features/preview">预览（图 / PDF / 代码 / 表格）</a></li><li><a href="/filebox/zh/features/browse">浏览文件</a> · <a href="/filebox/zh/features/explorer">Explorer</a> · <a href="/filebox/zh/features/collections">合集</a></li></ul>',26)])])}const P=i(c,[["render",h]]);export{x as __pageData,P as default};
